 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            r0 = min(rr for rr, _ in component)
            r1 = max(rr for rr, _ in component)
            c0 = min(cc for _, cc in component)
            c1 = max(cc for _, cc in component)
            cells = set(component)
            # A rectangular frame with one missing cell on its top edge.
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            boundary = {(rr, cc) for rr in range(r0, r1+1) for cc in range(c0, c1+1)
                        if rr in (r0, r1) or cc in (c0, c1)}
            missing_top = [(r0, cc) for cc in range(c0+1, c1) if (r0, cc) not in cells]
            if len(missing_top) != 1 or cells != boundary - {missing_top[0]}:
                continue
            _, gap_c = missing_top[0]
            # Color the opening and the cavity, then extend the beam leftward
            # across the row immediately above the frame, ending at the opening column.
            out[r0][gap_c] = 2
            for rr in range(r0+1, r1):
                for cc in range(c0+1, c1):
                    out[rr][cc] = 2
            if r0 > 0:
                for cc in range(gap_c+1):
                    out[r0-1][cc] = 2
    return out
